int vulnerable_buffer_copy(char *src, int len) {
    char dest[64];
    if (len > 0) {
        strcpy(dest, src);
    }
    return 0;
}

int safe_buffer_copy(char *src, int len) {
    char dest[64];
    if (len > 0 && len < 64) {
        strncpy(dest, src, sizeof(dest) - 1);
        dest[sizeof(dest) - 1] = '\0';
    }
    return 0;
}
